{
  "milestones": [
    {
      "task": "find smooth_sandstone_stairs",
      "milestone_id": "find_smooth_sandstone_stairs",
      "description": "Uses position_near_with_facing because this is a 'find' task — the player must navigate near the smooth sandstone stairs and face them to demonstrate they've located them. The stairs are centered at approximately (4, 0, 9) relative to spawn. max_distance=16 allows detection from a reasonable range, and facing_tolerance=60 ensures the player is looking toward the stairs.",
      "rules": [
        {
          "type": "position_near_with_facing",
          "params": {
            "target": [4, 0, 9],
            "max_distance": 16,
            "facing_tolerance": 60,
            "coordinate_frame": "spawn_relative"
          }
        }
      ]
    },
    {
      "task": "find red_stained_glass",
      "milestone_id": "find_red_stained_glass",
      "description": "Uses position_near_with_facing because this is a 'find' task — the player must navigate near the red stained glass windows and face them. The glass windows are centered at approximately (10, 3, 6) on the front wall of the temple. max_distance=16 allows the player to see the distinctive red glass from a comfortable distance, and facing_tolerance=60 ensures they are looking toward the windows.",
      "rules": [
